mapper.select:
SELECT auto_saving_id AS autoSavingId, user_id AS userId, money_box_id AS moneyBoxId, account_id AS accountId, max_amount AS maxAmount, auto_saving_status AS autoSavingStatus FROM auto_saving WHERE auto_saving_status = 'ACTIVE'
AND user_id = #{userId}
ORDER BY auto_saving_id

SELECT DATE_FORMAT(h.transacted_at, '%Y-%m-%d') AS date,
       'SAVED'                                  AS status,
       h.amount                                 AS amount,
       NULL                                     AS description
FROM auto_saving_history h
       JOIN auto_saving a
            ON h.auto_saving_id = a.auto_saving_id
WHERE a.user_id = #{userId}
  AND h.transacted_at >= #{startDateTime}
  AND h.transacted_at < #{endDateTime}
ORDER BY h.transacted_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM auto_saving_history h
       JOIN auto_saving a
            ON h.auto_saving_id = a.auto_saving_id
WHERE a.user_id = #{userId}
  AND h.transacted_at >= #{startDateTime}
  AND h.transacted_at < #{endDateTime}

mapper.update:
UPDATE auto_saving
SET max_amount = #{maxAmount}
WHERE auto_saving_id = #{autoSavingId}
  AND user_id = #{userId}

UPDATE auto_saving
SET auto_saving_status = #{status}
WHERE auto_saving_id = #{autoSavingId}
  AND user_id = #{userId}
